def compress(self, string):
if string is None or not string:
return string
result = ''
prev_char = string[0]
count = 0
for char in string:
if char == prev_char:
count += 1
else:
result += self._calc_partial_result(prev_char, count)
prev_char = char
count = 1
result += self._calc_partial_result(prev_char, count)
return result if len(result) < len(string) else string

rust_replacement:
impl CompressString {
    pub fn compress(string: Option<&str>) -> Option<String> {
        let string = match string {
            None => return None,
            Some(s) if s.is_empty() => return Some(String::new()),
            Some(s) => s,
        };
        let mut result = String::new();
        let mut chars = string.chars();
        let mut prev_char = chars.next().unwrap();
        let mut count: usize = 0;
        for ch in string.chars() {
            if ch == prev_char {
                count += 1;
            } else {
                result.push_str(&Self::calc_partial_result(prev_char, count));
                prev_char = ch;
                count = 1;
            }
        }
        result.push_str(&Self::calc_partial_result(prev_char, count));
        if result.len() < string.len() {
            Some(result)
        } else {
            Some(string.to_string())
        }
    }
}

impl CompressString {
    fn calc_partial_result(prev_char: char, count: usize) -> String {
        if count > 1 {
            format!("{}{}", prev_char, count)
        } else {
            prev_char.to_string()
        }
    }
}

#[test]
fn test_compress() {
    assert_eq!(CompressString::compress(None), None);
    assert_eq!(CompressString::compress(Some("")), Some(String::new()));
    assert_eq!(CompressString::compress(Some("AABBCC")), Some("AABBCC".to_string()));
    assert_eq!(CompressString::compress(Some("AAABCCDDDDE")), Some("A3BC2D4E".to_string()));
    assert_eq!(CompressString::compress(Some("BAAACCDDDD")), Some("BA3C2D4".to_string()));
    assert_eq!(CompressString::compress(Some("AAABAACCDDDD")), Some("A3BA2C2D4".to_string()));
    println!("Success: test_compress");
}

