impl ReverseString {
    pub fn reverse_in_place(&self, chars: Option<Vec<char>>) -> Option<Vec<char>> {
        let mut chars = chars?;
        if chars.is_empty() {
            return Some(chars);
        }
        let size = chars.len();
        for i in 0..(size / 2) {
            chars.swap(i, size - 1 - i);
        }
        Some(chars)
    }
}

