impl Stacks {
    pub fn push(&mut self, stack_index: usize, data: i64) {
        if self.stack_pointers[stack_index] == self.stack_size as isize - 1 {
            panic!("Stack is full");
        }
        self.stack_pointers[stack_index] += 1;
        let array_index = self.abs_index(stack_index);
        self.stack_array[array_index] = Some(data);
    }
}

impl Stacks {
    pub fn pop(&mut self, stack_index: usize) -> i64 {
        if self.stack_pointers[stack_index] == -1 {
            panic!("Stack is empty");
        }
        let array_index = self.abs_index(stack_index);
        let data = self.stack_array[array_index].take();
        self.stack_pointers[stack_index] -= 1;
        data.expect("Stack is empty")
    }
}

