#[derive(Debug)]
pub struct LoopNode {
    pub data: i64,
    pub next: Option<Rc<RefCell<LoopNode>>>,
}

impl LoopNode {
    pub fn new(data: i64) -> Self {
        LoopNode { data, next: None }
    }
