#[derive(Debug)]
pub struct MyLinkedList {
    pub head: Option<Rc<RefCell<LoopNode>>>,
}

impl MyLinkedList {
    pub fn new() -> Self {
        MyLinkedList { head: None }
    }

    pub fn append(&mut self, data: i64) {
        let node = Rc::new(RefCell::new(LoopNode::new(data)));
        match self.head.clone() {
            None => {
                self.head = Some(node);
            }
            Some(head) => {
                let mut curr = head;
                loop {
                    let next = curr.borrow().next.clone();
                    match next {
                        None => {
                            curr.borrow_mut().next = Some(node);
                            break;
                        }
                        Some(next) => {
                            curr = next;
                        }
                    }
                }
            }
        }
    }
}

