impl MyLinkedList {
    pub fn find_loop_start(&self) -> Option<Rc<RefCell<LoopNode>>> {
        let head = self.head.clone()?;
        if head.borrow().next.is_none() {
            return None;
        }
        let mut slow = head.clone();
        let mut fast = head.clone();
        loop {
            let fast_next = fast.borrow().next.clone();
            let fast_next = match fast_next {
                None => return None,
                Some(next) => next,
            };
            let slow_next = slow.borrow().next.clone();
            let slow_next = match slow_next {
                None => return None,
                Some(next) => next,
            };
            slow = slow_next;
            let fast_next2 = fast_next.borrow().next.clone();
            fast = match fast_next2 {
                None => return None,
                Some(next_next) => next_next,
            };
            if Rc::ptr_eq(&slow, &fast) {
                break;
            }
        }
        slow = head;
        loop {
            if Rc::ptr_eq(&slow, &fast) {
                return Some(slow);
            }
            let slow_next = slow.borrow().next.clone();
            slow = match slow_next {
                None => return None,
                Some(next) => next,
            };
            let fast_next = fast.borrow().next.clone();
            fast = match fast_next {
                None => return None,
                Some(next) => next,
            };
        }
    }
}

