impl GraphPathExists {
    pub fn path_exists(&mut self, start: Option<usize>, end: Option<usize>) -> bool {
        let (Some(s), Some(e)) = (start, end) else { return false; };
        if s == e { return true; }
        let mut queue: VecDeque<usize> = VecDeque::new();
        queue.push_back(s);
        if let Some(n) = self.nodes.get_mut(&s) { n.visit_state = State::Visited; }
        while let Some(id) = queue.pop_front() {
            if id == e { return true; }
            let next: Vec<usize> = self.nodes.get(&id).map(|n| n.adj_nodes.keys().copied().collect()).unwrap_or_default();
            for a in next {
                let unvisited = matches!(self.nodes.get(&a), Some(n) if n.visit_state == State::Unvisited);
                if unvisited {
                    queue.push_back(a);
                    if let Some(n) = self.nodes.get_mut(&a) { n.visit_state = State::Visited; }
                }
            }
        }
        false
    }
}

