pub struct PriorityQueueNode {
    pub key: String,
    pub weight: i64,
}
pub struct PriorityQueue {
    heap: BinaryHeap<(Reverse<i64>, String)>,
    current: HashMap<String, i64>,
}
impl PriorityQueue {
    pub fn new() -> Self { Self { heap: BinaryHeap::new(), current: HashMap::new() } }
    pub fn is_empty(&self) -> bool { self.heap.is_empty() }
    pub fn insert(&mut self, node: PriorityQueueNode) {
        self.current.insert(node.key.clone(), node.weight);
        self.heap.push((Reverse(node.weight), node.key));
    }
    pub fn decrease_key(&mut self, key: &str, weight: i64) {
        self.insert(PriorityQueueNode { key: key.to_string(), weight });
    }
    pub fn extract_min(&mut self) -> Option<PriorityQueueNode> {
        while let Some((Reverse(w), k)) = self.heap.pop() {
            if self.current.get(&k) == Some(&w) {
                return Some(PriorityQueueNode { key: k, weight: w });
            }
        }
        None
    }
}
pub struct ShortestPath {
    pub graph: Graph,
    pub previous: HashMap<String, Option<String>>,
    pub path_weight: HashMap<String, i64>,
    pub remaining: PriorityQueue,
}
// NOTE: Python class translated to struct.

impl ShortestPath {
    pub fn new(graph: Graph) -> Self {
        let mut previous = HashMap::new();
        let mut path_weight = HashMap::new();
        let mut remaining = PriorityQueue::new();
        for key in graph.nodes.keys() {
            previous.insert(key.clone(), None);
            path_weight.insert(key.clone(), i64::MAX);
            remaining.insert(PriorityQueueNode { key: key.clone(), weight: i64::MAX });
        }
        Self { graph, previous, path_weight, remaining }
    }
}

impl ShortestPath {
    pub fn find_shortest_path(&mut self, start_node_key: &str, end_node_key: &str) -> Vec<String> {
        if !self.graph.nodes.contains_key(start_node_key) || !self.graph.nodes.contains_key(end_node_key) {
            panic!("Invalid start or end node key");
        }
        self.path_weight.insert(start_node_key.to_string(), 0);
        self.remaining.decrease_key(start_node_key, 0);
        while !self.remaining.is_empty() {
            let min_key = self.remaining.extract_min().unwrap_or(PriorityQueueNode { key: String::new(), weight: i64::MAX }).key;
            let min_node = self.graph.nodes.get(&min_key).cloned().unwrap_or_default();
            for adj_key in min_node.adj_nodes.keys() {
                let new_weight = min_node.adj_weights[adj_key] + self.path_weight[&min_key];
                if self.path_weight[adj_key] > new_weight {
                    self.previous.insert(adj_key.clone(), Some(min_key.clone()));
                    self.path_weight.insert(adj_key.clone(), new_weight);
                    self.remaining.decrease_key(adj_key, new_weight);
                }
            }
        }
        let mut result = Vec::new();
        let mut current: Option<String> = Some(end_node_key.to_string());
        while let Some(k) = current {
            result.push(k.clone());
            current = self.previous.get(&k).cloned().flatten();
        }
        result.reverse();
        result
    }
}

