impl BinaryTree {
    fn lca_inner(root: Link, node1: Link, node2: Link) -> Link {
        let Some(r) = root else { return None; };
        let is_n1 = node1.as_ref().is_some_and(|n| Rc::ptr_eq(&r, n));
        let is_n2 = node2.as_ref().is_some_and(|n| Rc::ptr_eq(&r, n));
        if is_n1 || is_n2 {
            return Some(r);
        }
        let left = Self::lca_inner(r.borrow().left.clone(), node1.clone(), node2.clone());
        let right = Self::lca_inner(r.borrow().right.clone(), node1, node2);
        match (left, right) {
            (Some(_), Some(_)) => Some(r),
            (Some(l), None) => Some(l),
            (None, Some(rr)) => Some(rr),
            (None, None) => None,
        }
    }
}

