def _lca(self, curr_node, node1, node2):
if curr_node is None:
return LcaResult(None, is_ancestor=False)
if curr_node is node1 and curr_node is node2:
return LcaResult(curr_node, is_ancestor=True)
left_result = self._lca(curr_node.left, node1, node2)
if left_result.is_ancestor:
return left_result
right_result = self._lca(curr_node.right, node1, node2)
if right_result.is_ancestor:
return right_result
if left_result.node is not None and right_result.node is not None:
return LcaResult(curr_node, is_ancestor=True)
elif curr_node is node1 or curr_node is node2:
is_ancestor = left_result.node is not None or \
right_result.node is not None
return LcaResult(curr_node, is_ancestor)
else:
return LcaResult(left_result.node if left_result.node is not None \
else right_result.node, is_ancestor=False)

rust_replacement:
impl BinaryTreeOptimized {
    fn lca_inner(curr: Link, node1: Link, node2: Link) -> LcaResult {
        let Some(c) = curr else {
            return LcaResult::new(None, false);
        };
        let is_both = node1.as_ref().is_some_and(|n| Rc::ptr_eq(&c, n))
            && node2.as_ref().is_some_and(|n| Rc::ptr_eq(&c, n));
        if is_both {
            return LcaResult::new(Some(c), true);
        }
        let left_result = Self::lca_inner(c.borrow().left.clone(), node1.clone(), node2.clone());
        if left_result.is_ancestor {
            return left_result;
        }
        let right_result = Self::lca_inner(c.borrow().right.clone(), node1.clone(), node2.clone());
        if right_result.is_ancestor {
            return right_result;
        }
        if left_result.node.is_some() && right_result.node.is_some() {
            return LcaResult::new(Some(c), true);
        }
        let is_self = node1.as_ref().is_some_and(|n| Rc::ptr_eq(&c, n))
            || node2.as_ref().is_some_and(|n| Rc::ptr_eq(&c, n));
        if is_self {
            let covered = left_result.node.is_some() || right_result.node.is_some();
            return LcaResult::new(Some(c), covered);
        }
        LcaResult::new(left_result.node.or(right_result.node), false)
    }
}

