        let mut results: Vec<Vec<i32>> = Vec::new();
        let mut current = vec![root];
        while !current.is_empty() {
            results.push(current.iter().map(|rc| rc.borrow().val).collect());
            let mut next = Vec::new();
            for parent in &current {
                if let Some(l) = parent.borrow().left.clone() { next.push(l); }
                if let Some(r) = parent.borrow().right.clone() { next.push(r); }
