impl Trie {
    pub fn insert(&mut self, word: Option<&str>) -> Result<(), String> {
        let word = word.ok_or("word cannot be None".to_string())?;
        let mut node = Rc::clone(&self.root);
        for ch in word.chars() {
            let next = node.borrow().children.get(&ch).map(Rc::clone);
            match next {
                Some(child) => node = child,
                None => {
                    let fresh = Node::new(ch, Some(Rc::clone(&node)), false);
                    node.borrow_mut().children.insert(ch, Rc::clone(&fresh));
                    node = fresh;
                }
            }
        }
        // NOTE: card's insert is truncated before marking the word end.
        node.borrow_mut().terminates = true;
        Ok(())
    }
}

