def _find_path(self, matrix, row, col, cache, path):
if row < 0 or col < 0 or not matrix[row][col]:
return False
cell = (row, col)
if cell in cache:
return cache[cell]
cache[cell] = (row == 0 and col == 0 or
self._find_path(matrix, row, col - 1, cache, path) or
self._find_path(matrix, row - 1, col, cache, path))
if cache[cell]:
path.append(cell)
return cache[cell]

rust_replacement:
impl Grid {
    fn find_path_inner(&self, matrix: &Vec<Vec<i64>>, row: isize, col: isize, cache: &mut std::collections::HashMap<(usize, usize), bool>, path: &mut Vec<(usize, usize)>) -> bool {
        if row < 0 || col < 0 || matrix[row as usize][col as usize] == 0 { return false; }
        let cell = (row as usize, col as usize);
        if let Some(&v) = cache.get(&cell) { return v; }
        let ok = (row == 0 && col == 0)
            || self.find_path_inner(matrix, row, col - 1, cache, path)
            || self.find_path_inner(matrix, row - 1, col, cache, path);
        cache.insert(cell, ok);
        if ok { path.push(cell); }
        ok
    }
}

