impl Subsequence {
    pub fn longest_inc_subseq(&self, seq: Option<&[i64]>) -> Result<Vec<i64>, String> {
        let seq = seq.ok_or("seq cannot be None".to_string())?;
        if seq.is_empty() { return Ok(vec![]); }
        let n = seq.len();
        let mut temp = vec![1i64; n];
        let mut prev: Vec<Option<usize>> = vec![None; n];
        for r in 1..n {
            for l in 0..r {
                if seq[l] < seq[r] && temp[r] < temp[l] + 1 {
                    temp[r] = temp[l] + 1;
                    prev[r] = Some(l);
                }
            }
        }
        let mut max_val = 0i64;
        let mut max_index: Option<usize> = None;
        for (index, &value) in temp.iter().enumerate() {
            if value > max_val { max_val = value; max_index = Some(index); }
        }
        let mut results = Vec::new();
        let mut curr = max_index;
        while let Some(i) = curr { results.push(seq[i]); curr = prev[i]; }
        results.reverse();
        Ok(results)
    }
}

