impl StringCompare {
    // NOTE: index order kept as in card (s0[j-1] vs s1[i-1]).
    pub fn longest_common_substr(&self, str0: Option<&str>, str1: Option<&str>) -> Result<String, String> {
        let str0 = str0.ok_or("str input cannot be None".to_string())?;
        let str1 = str1.ok_or("str input cannot be None".to_string())?;
        let s0: Vec<char> = str0.chars().collect();
        let s1: Vec<char> = str1.chars().collect();
        let num_rows = s0.len() + 1;
        let num_cols = s1.len() + 1;
        let mut t = vec![vec![0usize; num_cols]; num_rows];
        for i in 0..num_rows {
            for j in 0..num_cols {
                if i == 0 || j == 0 { t[i][j] = 0; }
                else if s0[j - 1] != s1[i - 1] { t[i][j] = t[i][j - 1].max(t[i - 1][j]); }
                else { t[i][j] = t[i - 1][j - 1] + 1; }
            }
        }
        let mut results = String::new();
        let (mut i, mut j) = (num_rows - 1, num_cols - 1);
        while t[i][j] != 0 {
            if t[i][j] == t[i][j - 1] { j -= 1; }
            else if t[i][j] == t[i - 1][j] { i -= 1; }
            else if t[i][j] == t[i - 1][j - 1] + 1 {
                results.push(s1[i - 1]);
                i -= 1;
                j -= 1;
            } else { panic!("Error constructing table"); }
        }
        Ok(results.chars().rev().collect())
    }
}

