def _find_magic_index(self, array, start, end):
if end < start or start < 0 or end >= len(array):
return -1
mid = (start + end) // 2
if mid == array[mid]:
return mid
left_end = min(mid - 1, array[mid])
left_result = self._find_magic_index(array, start, end=left_end)
if left_result != -1:
return left_result
right_start = max(mid + 1, array[mid])
right_result = self._find_magic_index(array, start=right_start, end=end)
if right_result != -1:
return right_result
return -1

rust_replacement:
impl MagicIndex {
    fn find_magic_index_inner(&self, array: &[i64], start: isize, end: isize) -> i64 {
        if end < start || start < 0 || end >= array.len() as isize { return -1; }
        let mid = (start + end) / 2;
        let mid_val = array[mid as usize];
        if mid == mid_val as isize { return mid as i64; }
        let left_end = std::cmp::min(mid - 1, mid_val as isize);
        let left = self.find_magic_index_inner(array, start, left_end);
        if left != -1 { return left; }
        let right_start = std::cmp::max(mid + 1, mid_val as isize);
        let right = self.find_magic_index_inner(array, right_start, end);
        if right != -1 { return right; }
        -1
    }
}

