impl MatrixMultiplicationCost {
    pub fn find_min_cost(&self, matrices: Option<&[Matrix]>) -> Result<usize, String> {
        let matrices = matrices.ok_or("matrices cannot be None".to_string())?;
        if matrices.is_empty() { return Ok(0); }
        let size = matrices.len();
        let mut t = vec![vec![0usize; size]; size];
        for offset in 1..size {
            for i in 0..(size - offset) {
                let j = i + offset;
                let mut min_cost = usize::MAX;
                for k in i..j {
                    let cost = t[i][k] + t[k + 1][j]
                        + (matrices[i].first as usize)
                        * (matrices[k].second as usize)
                        * (matrices[j].second as usize);
                    if cost < min_cost { min_cost = cost; }
                }
                t[i][j] = min_cost;
            }
        }
        Ok(t[0][size - 1])
    }
}

