impl StockTrader {
    fn find_max_profit_transactions(&self, t: &[Vec<i64>], prices: &[i64]) -> (i64, Vec<Transaction>) {
        let mut results = Vec::new();
        let mut i = t.len() - 1;
        let mut j = t[0].len() - 1;
        let max_profit = t[i][j];
        while i != 0 && j != 0 {
            if t[i][j] == t[i][j - 1] { j -= 1; }
            else {
                let sell_price = prices[j];
                results.push(Transaction::new(Type::SELL, j, sell_price));
                let profit = t[i][j] - t[i - 1][j - 1];
                i -= 1;
                j -= 1;
                for m in (0..=j).rev() {
                    if sell_price - prices[m] == profit {
                        results.push(Transaction::new(Type::BUY, m, prices[m]));
                        break;
                    }
                }
            }
        }
        (max_profit, results)
    }
}

