    fn _count_ways(&self, n: i64, cache: &mut std::collections::HashMap<i64, i64>) -> i64 {
        if n < 0 {
            return 0;
        }
        if n == 0 {
            return 1;
        }
        if let Some(&v) = cache.get(&n) {
            return v;
        }
        let total = self._count_ways(n - 1, cache) + self._count_ways(n - 2, cache) + self._count_ways(n - 3, cache);
        cache.insert(n, total);
        total
    }
}

