impl Anagram {
    pub fn group_anagrams(&self, items: Option<Vec<String>>) -> Result<Vec<String>, String> {
        let items = match items {
            None => return Err("items cannot be None".to_string()),
            Some(v) => v,
        };
        if items.is_empty() {
            return Ok(items);
        }
        let mut map: Vec<(Vec<char>, Vec<String>)> = Vec::new();
        for item in &items {
            let mut key: Vec<char> = item.chars().collect();
            key.sort_unstable();
            match map.iter_mut().find(|(k, _)| *k == key) {
                Some((_, g)) => g.push(item.clone()),
                None => map.push((key, vec![item.clone()])),
            }
        }
        let mut result = Vec::new();
        for (_, g) in map {
            result.extend(g);
        }
        Ok(result)
    }
}

