        let (mut source, dest) = match (source, dest) {
            (Some(s), Some(d)) => (s, d),
            _ => return Err("source or dest cannot be None".to_string()),
        };
        let (se, de) = match (source_end_index, dest_end_index) {
            (Some(s), Some(d)) if s >= 0 && d >= 0 => (s as usize, d as usize),
            (Some(_), Some(_)) => return Err("end indices must be >= 0".to_string()),
            _ => return Err("end indices cannot be None".to_string()),
        };
        if source.is_empty() {
            return Ok(dest);
        }
        if dest.is_empty() {
            return Ok(source);
        }
        // NOTE: card compares slots directly; None only sits in the trailing buffer.
        let mut si = se as i64 - 1;
        let mut di = de as i64 - 1;
        let mut ii = (se + de) as i64 - 1;
        while di >= 0 {
            if source[si as usize] > dest[di as usize] {
                source[ii as usize] = source[si as usize];
                si -= 1;
            } else {
                source[ii as usize] = dest[di as usize];
                di -= 1;
            }
            ii -= 1;
        }
        Ok(source)
    }
}

