    pub fn sort(&self, data: Option<Vec<i64>>) -> Result<Vec<i64>, String> {
        let data = match data {
            None => return Err("data cannot be None".to_string()),
            Some(d) => d,
        };
        Ok(self._sort(data))
    }
    fn _sort(&self, data: Vec<i64>) -> Vec<i64> {
        if data.len() < 2 {
            return data;
        }
        let (mut equal, mut left, mut right) = (Vec::new(), Vec::new(), Vec::new());
        let pivot = data[data.len() / 2];
        for item in &data {
            if *item == pivot {
                equal.push(*item);
            } else if *item < pivot {
                left.push(*item);
            } else {
                right.push(*item);
            }
        }
        let mut sorted = self._sort(left);
        sorted.extend(equal);
        sorted.extend(self._sort(right));
        sorted
    }
}

