impl RadixSort {
    pub fn sort(&self, array: Option<&[i64]>, base: i64) -> Result<Vec<i64>, String> {
        let array = array.ok_or_else(|| "array cannot be None".to_string())?;
        if array.is_empty() {
            return Ok(Vec::new());
        }
        // NOTE: card takes abs() of the max for digit counting; negative
        // inputs would mis-bucket, same as the card's integer division.
        let max_element = *array.iter().max().unwrap();
        let max_digits = max_element.abs().to_string().len();
        let mut curr: Vec<i64> = array.to_vec();
        for digit in 0..max_digits {
            let mut buckets: Vec<Vec<i64>> = vec![Vec::new(); base as usize];
            let div = base.pow(digit as u32);
            for &item in &curr {
                buckets[((item / div) % base) as usize].push(item);
            }
            curr = buckets.into_iter().flatten().collect();
        }
        Ok(curr)
    }
}

