impl Array {
    fn _search_sorted_array(&self, array: &[i64], val: i64, start: i64, end: i64) -> Option<usize> {
        if end < start {
            return None;
        }
        let mid = (start + end) / 2;
        let m = mid as usize;
        if array[m] == val {
            return Some(m);
        }
        if array[start as usize] < array[m] {
            if array[start as usize] <= val && val < array[m] {
                return self._search_sorted_array(array, val, start, mid - 1);
            } else {
                return self._search_sorted_array(array, val, mid + 1, end);
            }
        } else if array[start as usize] > array[m] {
            if array[m] < val && val <= array[end as usize] {
                return self._search_sorted_array(array, val, mid + 1, end);
            } else {
                return self._search_sorted_array(array, val, start, mid - 1);
            }
        } else {
            if array[m] != array[end as usize] {
                return self._search_sorted_array(array, val, mid + 1, end);
            } else {
                let result = self._search_sorted_array(array, val, start, mid - 1);
                if result.is_some() {
                    return result;
                } else {
                    return self._search_sorted_array(array, val, mid + 1, end);
                }
            }
        }
    }
}

