            self.max = Some(val);
        }
        if self.min.is_none() || val < self.min.unwrap() {
            self.min = Some(val);
        }
        self.num_items += 1;
        self.running_sum += val;
        self.mean = Some(self.running_sum as f64 / self.num_items as f64);
