impl Solution {
    pub fn merge_ranges(&self, array: Option<&[(i64, i64)]>) -> Result<Vec<(i64, i64)>, String> {
        let array = array.ok_or_else(|| "array cannot be None".to_string())?;
        if array.is_empty() {
            return Ok(Vec::new());
        }
        // NOTE: (i64, i64) tuples sort lexicographically like Python tuples.
        let mut sorted_array = array.to_vec();
        sorted_array.sort();
        let mut merged = vec![sorted_array[0]];
        for (index, &item) in sorted_array.iter().enumerate() {
            if index == 0 {
                continue;
            }
            let (start_prev, end_prev) = *merged.last().unwrap();
            let (start_curr, end_curr) = item;
            if end_prev < start_curr {
                merged.push(item);
            } else {
                *merged.last_mut().unwrap() = (start_prev, end_prev.max(end_curr));
            }
        }
        Ok(merged)
    }
}

