impl Solution {
    pub fn max_prod_three(&self, array: Option<&[i64]>) -> Result<i64, String> {
        let array = array.ok_or_else(|| "array cannot be None".to_string())?;
        if array.len() < 3 {
            return Err("array must have 3 or more ints".to_string());
        }
        let mut curr = array[0] * array[1] * array[2];
        let mut max_two = array[0] * array[1];
        let mut min_two = array[0] * array[1];
        let mut max_num = array[0].max(array[1]);
        let mut min_num = array[0].min(array[1]);
        for &x in &array[2..] {
            curr = curr.max(max_two * x).max(min_two * x);
            max_two = max_two.max(max_num * x).max(min_num * x);
            min_two = min_two.min(max_num * x).min(min_num * x);
            max_num = max_num.max(x);
            min_num = min_num.min(x);
        }
        Ok(curr)
    }
}

