        let mut num_copy = num;
        while num_copy != 0 && num_copy & 1 == 0 {
            num_zeroes += 1;
            num_copy >>= 1;
        }
        while num_copy != 0 && num_copy & 1 == 1 {
            num_ones += 1;
            num_copy >>= 1;
        }
        // NOTE: Python ints are unbounded; i64 shifts assume index < 63.
        let index = num_zeroes + num_ones;
        num |= 1 << index;
        num &= !((1 << index) - 1);
        let ones_mask = if num_ones == 0 { 0 } else { (1 << (num_ones - 1)) - 1 };
        num |= ones_mask;
        Ok(num)
    }
}

impl Bits {
    /// Next smallest integer with the same number of 1-bits.
    pub fn get_next_smallest(&self, num: Option<i64>) -> Result<i64, String> {
        let mut num = match num {
            Some(n) => n,
            None => return Err("num cannot be None".to_string()),
        };
        if num <= 0 {
            return Err("num cannot be 0 or negative".to_string());
        }
        let mut num_ones = 0i64;
        let mut num_zeroes = 0i64;
        let mut num_copy = num;
        while num_copy != 0 && num_copy & 1 == 1 {
            num_ones += 1;
            num_copy >>= 1;
        }
        while num_copy != 0 && num_copy & 1 == 0 {
            num_zeroes += 1;
            num_copy >>= 1;
        }
        // NOTE: Python ints are unbounded; i64 shifts assume index < 63.
        let index = num_zeroes + num_ones;
        num &= !(1 << index);
        num &= !((1 << index) - 1);
        num |= (1 << (num_ones + 1)) - 1;
        Ok(num)
    }
}

