def sum_of_two(self, a, b):
if a is None or b is None:
raise TypeError('a or b cannot be None')
MAX = 0x7FFFFFFF  # 32 bit integer max valid value
MASK = 0xFFFFFFFF  # Get the last 32 bits
result = (a ^ b) & MASK
carry = ((a & b) << 1) & MASK
if carry != 0:
return self.sum_of_two(result, carry)
if result <= MAX:
return result
else:
# Get the 32-bit positive complement with ^
# and convert to the Python complement with ~
return ~(result ^ MASK)

