            (Some(a), Some(b)) => (a, b),
            _ => return Err("a or b cannot be None".to_string()),
        };
        const MAX: i64 = 0x7FFFFFFF;
        const MASK: i64 = 0xFFFFFFFF;
        let result = (a ^ b) & MASK;
        let carry = ((a & b) << 1) & MASK;
        // NOTE: 32-bit mask emulates the card; i64 shifts assume small operands.
