use std::collections::HashMap;

impl Solution {
    pub fn two_sum(&self, nums: Option<&[i64]>, target: Option<i64>) -> Result<Option<Vec<i64>>, String> {
        let (nums, target) = match (nums, target) {
            (Some(n), Some(t)) => (n, t),
            _ => return Err("nums or target cannot be None".to_string()),
        };
        if nums.is_empty() {
            return Err("nums cannot be empty".to_string());
        }
        let mut cache: HashMap<i64, usize> = HashMap::new();
        for (index, &num) in nums.iter().enumerate() {
            let cache_target = target - num;
            if let Some(&prev) = cache.get(&num) {
                return Ok(Some(vec![prev as i64, index as i64]));
            } else {
                cache.insert(cache_target, index);
            }
        }
        Ok(None)
    }
}

