impl Knapsack {
    pub fn fill_knapsack(
        &self,
        input_items: Option<&[Item]>,
        total_weight: Option<usize>,
    ) -> Result<Vec<Item>, String> {
        let (input_items, total_weight) = match (input_items, total_weight) {
            (Some(items), Some(w)) => (items, w),
            _ => return Err("input_items or total_weight cannot be None".to_string()),
        };
        // NOTE: the card returns 0 for empty input; Rust returns an empty Vec instead.
        if input_items.is_empty() || total_weight == 0 {
            return Ok(Vec::new());
        }
        let mut items = vec![Item::new("", 0, 0)];
        items.extend_from_slice(input_items);
        let num_rows = items.len();
        let num_cols = total_weight + 1;
        let mut t = vec![vec![0i64; num_cols]; num_rows];
        for i in 0..num_rows {
            for j in 0..num_cols {
                if i == 0 || j == 0 {
                    t[i][j] = 0;
                } else if j >= items[i].weight {
                    t[i][j] = (items[i].value + t[i - 1][j - items[i].weight]).max(t[i - 1][j]);
                } else {
                    t[i][j] = t[i - 1][j];
                }
            }
        }
        let mut results = Vec::new();
        let mut i = num_rows - 1;
        let mut j = num_cols - 1;
        // NOTE: usize indices mirror the card; saturating ops keep malformed states panic-free.
        while t[i][j] != 0 {
            if i > 0 && t[i - 1][j] == t[i][j] {
                i -= 1;
            } else if j > 0 && t[i][j - 1] == t[i][j] {
                j -= 1;
            } else {
                results.push(items[i].clone());
                if i == 0 {
                    break;
                }
                i -= 1;
                j = j.saturating_sub(items[i].weight);
            }
        }
        Ok(results)
    }
}

