    let prev = if index == 0 { items.len() - 1 } else { index - 1 };
    if total_weight == 0 || index >= items.len() {
        return KnapsackResult::new(items[prev].value, Some(items[prev].clone()));
    }
    if let Some(cached) = memo.get(&(total_weight, items.len() - index - 1)) {
        let weight = cached.total_weight + items[prev].value;
        return KnapsackResult::new(weight, Some(items[prev].clone()));
