        let ransom_note = ransom_note.ok_or("ransom_note or magazine cannot be None".to_string())?;
        let magazine = magazine.ok_or("ransom_note or magazine cannot be None".to_string())?;
        use std::collections::HashMap;
        let mut seen: HashMap<char, i64> = HashMap::new();
        for ch in magazine.chars() {
            *seen.entry(ch).or_insert(0) += 1;
        }
        for ch in ransom_note.chars() {
            match seen.get_mut(&ch) {
                None => return Ok(false),
                Some(count) => {
                    *count -= 1;
                    if *count < 0 {
                        return Ok(false);
                    }
                }
            }
        }
        Ok(true)
    }
}

