impl GraphShortestPath {
    fn shortest_path_prev(&mut self, source_key: i64, dest_key: i64) -> Option<HashMap<i64, Option<i64>>> {
        use std::collections::VecDeque;
        for node in self.inner.nodes.values_mut() {
            node.visit_state = State::Unvisited;
        }
        if !self.inner.nodes.contains_key(&source_key) {
            return None;
        }
        let mut queue: VecDeque<i64> = VecDeque::new();
        queue.push_back(source_key);
        let mut prev: HashMap<i64, Option<i64>> = HashMap::new();
        prev.insert(source_key, None);
        if let Some(n) = self.inner.nodes.get_mut(&source_key) {
            n.visit_state = State::Visited;
        }
        while let Some(key) = queue.pop_front() {
            if key == dest_key {
                return Some(prev);
            }
            let neighbors = self.inner.nodes.get(&key).map(|n| n.adj.clone()).unwrap_or_default();
            for adj in neighbors {
                let unvisited = matches!(self.inner.nodes.get(&adj).map(|n| n.visit_state), Some(State::Unvisited));
                if unvisited {
                    queue.push_back(adj);
                    prev.insert(adj, Some(key));
                    if let Some(n) = self.inner.nodes.get_mut(&adj) {
                        n.visit_state = State::Visited;
                    }
                }
            }
        }
        None
    }
}

