impl Solution {
    pub fn longest_substr(&self, string: Option<&str>, k: Option<i64>) -> Result<i64, String> {
        use std::collections::HashMap;
        let string = string.ok_or("string must be of type str".to_string())?;
        let k = k.ok_or("k must be of type int".to_string())?;
        let chars: Vec<char> = string.chars().collect();
        let mut low: usize = 0;
        let mut max_len: i64 = 0;
        let mut pos: HashMap<char, usize> = HashMap::new();
        for (index, ch) in chars.iter().enumerate() {
            pos.insert(*ch, index);
            if pos.len() as i64 > k {
                let low_index = *pos.values().min().unwrap();
                pos.remove(&chars[low_index]);
                low = low_index + 1;
            }
            let len = (index - low + 1) as i64;
            if len > max_len {
                max_len = len;
            }
        }
        Ok(max_len)
    }
}

