        let file_system = file_system.ok_or("file_system must be a string".to_string())?;
        let mut max_len: i64 = 0;
        let mut path_len: HashMap<usize, usize> = HashMap::new();
        path_len.insert(0, 0);
        for line in file_system.split('\n') {
            let name = line.trim_start_matches('\t');
            let depth = line.len() - name.len();
            if name.contains('.') {
                let cand = path_len[&depth] + name.len();
                if cand as i64 > max_len {
                    max_len = cand as i64;
                }
            } else {
                let v = path_len[&depth] + name.len() + 1;
                path_len.insert(depth + 1, v);
            }
        }
        Ok(max_len)
    }
}

#[test]
fn test_length_longest_path() {
    let solution = Solution;
    assert!(solution.length_longest_path(None).is_err());
    let fs = "dir\n\tsubdir1\n\t\tfile1.ext\n\t\tsubsubdir1\n\tsubdir2\n\t\tsubsubdir2\n\t\t\tfile2.ext";
    assert_eq!(solution.length_longest_path(Some(fs)).unwrap(), 32);
    println!("Success: test_length_longest_path");
}

