def count_sentence_fit(self, sentence, rows, cols):
try:
iter(sentence)
except TypeError:
raise TypeError('sentence must be of type str')
if not isinstance(rows, int) or not isinstance(cols, int):
raise TypeError('rows and cols must be of type int')
if rows < 0 or cols < 0:
raise ValueError('rows and cols cannot be negative')
if cols == 0 or not sentence:
return 0
string = ' '.join(sentence) + ' '
start = 0
str_len = len(string)
for row in range(rows):
start += cols
# We don't need extra space for the current row
if string[start % str_len] == ' ':
start += 1
# The current row can't fit, so we'll need to
# remove characters from the next word
else:
while (start > 0 and string[(start - 1) % str_len] != ' '):
start -= 1
return start // str_len

rust_replacement:
impl Solution {
    pub fn count_sentence_fit(&self, sentence: &[String], rows: i64, cols: i64) -> i64 {
        if sentence.is_empty() {
            return 0;
        }
        let string: String = sentence.join(" ") + " ";
        let bytes = string.as_bytes();
        let str_len = bytes.len() as i64;
        let mut start: i64 = 0;
        for _ in 0..rows {
            start += cols;
            if bytes[(start % str_len) as usize] == b' ' {
                start += 1;
            } else {
                while start > 0 && bytes[((start - 1) % str_len) as usize] != b' ' {
                    start -= 1;
                }
            }
        }
        start / str_len
    }
}

