    assert_eq!(solution.count_sentence_fit(&["hello".to_string(), "world".to_string()], 2, 8), 1);
    assert_eq!(solution.count_sentence_fit(&["a".to_string(), "bcd".to_string(), "e".to_string()], 3, 6), 2);
    println!("Success: test_count_sentence_fit");
}

