def format_license_key(self, license_key, k):
if not isinstance(license_key, str):
raise TypeError('license_key must be a str')
if not isinstance(k, int):
raise TypeError('k must be an int')
if not license_key:
raise ValueError('license_key must not be empty')
formatted_license_key = []
num_chars = 0
for char in license_key[::-1]:
if char == '-':
continue
num_chars += 1
formatted_license_key.append(char.upper())
if num_chars >= k:
formatted_license_key.append('-')
num_chars = 0
if formatted_license_key and formatted_license_key[-1] == '-':
formatted_license_key.pop(-1)
return ''.join(formatted_license_key[::-1])

rust_replacement:
impl Solution {
    pub fn format_license_key(license_key: &str, k: usize) -> Result<String, String> {
        if license_key.is_empty() {
            return Err("license_key must not be empty".to_string());
        }
        if k == 0 {
            return Err("k must be positive".to_string());
        }
        let mut out: Vec<char> = Vec::new();
        let mut num_chars = 0;
        for ch in license_key.chars().rev() {
            if ch == '-' {
                continue;
            }
            num_chars += 1;
            out.push(ch.to_ascii_uppercase());
            if num_chars >= k {
                out.push('-');
                num_chars = 0;
            }
        }
        if out.last() == Some(&'-') {
            out.pop();
        }
        out.reverse();
        Ok(out.into_iter().collect())
    }
}

#[test]
fn test_format_license_key() {
    assert_eq!(Solution::format_license_key("2-4A0r7-4k", 3), Ok("24-A0R-74K".to_string()));
    println!("Success: test_format_license_key");
}

