def find_busiest_period(self, data):
if data is None:
raise TypeError('data cannot be None')
if not data:
return None
data.sort()
max_period = Period(0, 0)
max_people = 0
curr_people = 0
for index, interval in enumerate(data):
if interval.event_type == EventType.ENTER:
curr_people += interval.num_people
elif interval.event_type == EventType.EXIT:
curr_people -= interval.num_people
else:
raise ValueError('Invalid event type')
if (index < len(data) - 1 and
data[index].timestamp == data[index + 1].timestamp):
continue
if curr_people > max_people:
max_people = curr_people
max_period.start = data[index].timestamp
if index < len(data) - 1:
max_period.end = data[index + 1].timestamp
else:
max_period.end = data[index].timestamp
return max_period

rust_replacement:
impl Solution {
    pub fn find_busiest_period(&self, data: Option<Vec<Data>>) -> Result<Option<Period>, String> {
        let mut data = data.ok_or("data cannot be None".to_string())?;
        if data.is_empty() {
            return Ok(None);
        }
        data.sort();
        let mut max_period = Period::new(0, 0);
        let mut max_people: i64 = 0;
        let mut curr_people: i64 = 0;
        for index in 0..data.len() {
            match data[index].event_type {
                EventType::Enter => curr_people += data[index].num_people,
                EventType::Exit => curr_people -= data[index].num_people,
            }
            if index < data.len() - 1 && data[index].timestamp == data[index + 1].timestamp {
                continue;
            }
            if curr_people > max_people {
                max_people = curr_people;
                max_period.start = data[index].timestamp;
                if index < data.len() - 1 {
                    max_period.end = data[index + 1].timestamp;
                } else {
                    max_period.end = data[index].timestamp;
                }
            }
        }
        Ok(Some(max_period))
    }
}

#[test]
fn test_find_busiest_period() {
    let solution = Solution;
    assert!(solution.find_busiest_period(None).is_err());
    assert_eq!(solution.find_busiest_period(Some(vec![])).unwrap(), None);
    let data = vec![
        Data::new(3, 2, EventType::Exit),
        Data::new(1, 2, EventType::Enter),
        Data::new(3, 1, EventType::Enter),
        Data::new(7, 3, EventType::Enter),
        Data::new(9, 2, EventType::Exit),
        Data::new(8, 2, EventType::Exit),
    ];
    assert_eq!(solution.find_busiest_period(Some(data)).unwrap(), Some(Period::new(7, 8)));
    println!("Success: test_find_busiest_period");
}

